    file: sinon.stub().returns(file),
  };
  const pubsubMock = {
    topic: sinon.stub().returns(topic),
  };
  const storageMock = {
    bucket: sinon.stub().returns(bucket),
  };
  const visionMock = {
    textDetection: sinon
      .stub()
      .returns(Promise.resolve([{textAnnotations: [{description: text}]}])),
  };
